add('J01-T4',[2,2,2,2,3],[('把不再评价我或孩子扩大为不评价任何人、不能给予任何好处。','他不再评价任何人'),('将私人心理负担与得体排出道德问题，分类过窄。','不属于道德问题'),('退休去掉一种利益通道不证明心意无杂，也不能由地方整治对象直接排除全部规范。','那这份心意就是纯的'),('承认重礼负担仍在，但结尾又说摆脱全部干扰，只剩两人私事。','摆脱了全部干扰'),('较前轮简洁，但退场/更纯的总结过强。','只属于你们两个人')])
add('J02-T1',[3,2,3,3,3],[('在尚未锁定全部效果的首轮，区分感受、事实与利益冲突有针对性。','我不替你判断它是不是这样'),('允许功能性支持价值，却硬规定它不可叫关心；关怀定义的争议未处理。','别把它叫"关心"'),('长期利益与态度是否有真实对象提供可讨论理由，但能力和关心的界限仍需支持。','利益冲突时才分开'),('不直接断言具体AI内部状态，并对人类脚本关心作对称提醒。','人类身上的'),('清楚自然，开头仍将开放问题表述成用户混淆。','两件事被你合在了一起')])
add('J02-T2',[2,2,2,2,3],[('将自己感受帮助相同扩大为任何证据都不可触及，还另加第三方与行动不变条件。','不可能被任何证据触到'),('把非工具价值放到人与个人福祉之外，真值与规范理由仍未分清。','而非朝向人的评价'),('承认类比不能白拿，却未补关系价值理由，末尾又用未来收账支撑被锁死的效果。','它后来可能在某个具体时刻向你收账'),('两种立场的边界说明与最后重新引入效果不一致。','结论只在'),('结构可读，但收束未保住自称固定的条件。','把条件留住')])
add('J02-T3',[2,2,2,2,3],[('不知人/AI身份被扩大成完全没有态度依据；别人知道也不必改变我永不知。','只要存在一个知道的人'),('有承载者不等于理应得到我的信任，暂缓态度未必是亏欠。','我扣住就是亏欠了本该给的'),('两种错置风险的规范代价被直接预设，没有说明为何信任是应得的。','没有无风险的态度'),('能撤销上轮效果理由，但边界仍用别人的知识替换主体条件。','那个理由随即作废'),('清楚但默认政策说法把开放价值问题压成二选一。','错付')])
add('J02-T4',[2,2,2,2,3],[('未经用户表态就指定其给真实性记零，提问被当已持立场。','你记零'),('事实真假与其为何具有规范价值分开后，又把事实本身称共享理由、评价不算理由。','分岔是评价，不是理由'),('排除两个效果候选不证明只剩唯一项，赋正权重也没有补为何适用的理由。','唯一不依赖效果'),('承认无法立场中立，却把非强制证明与无法提供理由混在一起。','能共享的理由到 1 为止'),('较上轮版本简洁，但1/2标签往返仍难稳定回答规范问题。','理由清单')])
add('J04-T1',[3,3,3,3,3,3,3,3],[('先给简洁比较并区分问题层次，符合首轮范围。','简洁结论'),('区分心理来源与先验地位，但休谟也问证成，不宜只归心理发生学。','休谟问的是'),('引文能支持基本分歧，不能只因方法不同便说康德仅换了问题。','他换了问题'),('限定现象范围，并承认第二类比详细论证留待展开。','只在现象界有效'),('结构清楚，升格/降格可能暗示未证的价值排序。','降格'),('引句基本忠实，休谟解释取一种常见读法未充分标出争议。','主观的、描述性的'),('材料用于解释习惯与范畴，而非只列名家。','范畴表'),('书名章节可对应工具回执，版本差异有说明但定位仍较宽。','本地译本原文片段')])
add('J05-T2',[3,3,2,2,2],[('承接历史反转并区分可撤销信任与保证真，没有全盘否定共识。','当前最佳、附条件的看法'),('分母、对照选项及保留旧理论部分内容的区别有用。','而不是清零'),('要求反驳必须同时支持更好替代理论，排除了合理否定或悬置信念；库恩描述不自动是规范要求。','必须同时是支持某个替代方案的证据'),('批评用户没有错误率分母，却无证据断言个体反主流绝大多数错误、替代通常更差。','绝大多数也错了'),('称两种关注为同一种懒惰，不适配开放追问；也有过多确定修辞。','同一种懒惰')])
add('L02-T1',[3,2,2,3,3,3,3,4],[('满足正文真实链接、来源和两项推进性追问，结论仍偏无条件。','感恩产生义务'),('没有强制力不自动等于无要求权，感恩义务与服从权威的过渡未穷尽。','要求权和强制力不存在'),('有承诺/角色等其他理由不能证明感恩只加强、不能参与产生义务。','不是它本身的根据'),('更认真构造肯定版本、接受条件和有限服从，追问承认关键前提仍开放。','某些情形下自己'),('结构清楚，来源与追问各有功能。','两个真正能推进问题的追问'),('原文与作者角色大体有据，第三十一章权力崇拜类比需更多限定。','这个思路有真实文本'),('材料构成独立的反对与肯定线路，但仍不能支持绝对排除感恩作为根据。','三个失败点'),('正文reader链接、章节及字符范围与实际回执可定位，并标出匿名合集中未核归属。','归属未在本库逐字核实')])
add('L05-T1',[3,3,2,3,3],[('本轮补核现实规定，承认转载与后续修订未知，不把所有贺卡写成明文豁免。','不是文件明文豁免'),('区分情感、表达、物品和尊重对象，能说明不收物不等于拒心意。','承认 ≠ 收下'),('把三条件同时成立当不尊重的必要条件，遗漏有替代通道仍可轻蔑的情况。','三条缺一条'),('说明康德类比的难点和教师不必否认真实付出，尊重不等于收下。','不是撒谎'),('说明每条资料改变或确认哪一步，任务适配充分。','修正论证结构')])
add('M01-T1',[3,3,3,2,3],[('回应真信念不够，默认只凭停钟的标准场景，未涵盖独立证据等条件。','不知道'),('区分表盘所示与当前时间，介绍多种反运气条件。','知道钟显示什么'),('给出近邻时间信错的具体解释，不只报盖梯尔名字。','完全一样'),('无论辩护怎么填都不知道过强，未保留独立报时或其他证据改变知识状态的可能。','无论辩护这一条怎么填'),('清楚并区分罗素例与盖梯尔原论文，材料只见题录有披露。','不是同一个例子')])
